    self._toggleData  = {}             --页签
    self._curSelectItmeInd = 0         --当前选中的下标
    self._curSelectGroupId = 0         --当前选中的组别id
end

function UIFshPoolCollectionDialog:__delete()
    self._allEasterEggsGroup = {}      --所有的彩蛋
    self._allEasterEggsId = {}         --所有的彩蛋id
    self._toggleData  = {}             --页签
    self._curSelectItmeInd = 0       --当前选中的下标
