function UIFshPoolCollectionDialog:InitData()
    self._toggleData  = {}       
    self._allEasterEggsGroup = {}
    local t = CfUtils.GetCfTable(AutoIds.IdSetting2026)
    if t then
        for k, v in pairs(t) do
            local vo = FishEasterEggsGroupVo.New()
            vo:FillVo(v)

            table.insert(self._toggleData, {
                type = checkString(vo.id),
                text = vo.name,
                func = function(node)
                    self._curSelectItmeInd = 1
                    self:RefreshCurTooggleType(vo.id)
                end,
                redPointStatus = FishingUtils.IsCanDrawReard(vo.id)
            })

            self._allEasterEggsGroup[checkString(vo.id)] = vo

            if checkNumber(self._curSelectGroupId) == 0 then
                self._curSelectGroupId = checkString(vo.id)
            end
        end  
    end
end

function UIFshPoolCollectionDialog:FillSelf()
    local scr = CfUtils.GetLuaScr(self.CommonTabToggleLeft, CommonTabToggleLeftPath)
    if scr then
        scr:FillToggles(self._toggleData)
    end

    self:RefreshCurTooggleType(self._curSelectGroupId)
    KTool.SetActive(self.Empty, true)
    KTool.SetActive(self.Content, false)
end

--刷新页签红点
function UIFshPoolCollectionDialog:RefreshRedPoint()
    local scr = CfUtils.GetLuaScr(self.CommonTabToggleLeft, CommonTabToggleLeftPath)
    if scr then
        for k, v in pairs(self._allEasterEggsGroup) do
            local node = scr:GetTogGoByIndex(0)
            local nodeScr = CfUtils.GetLuaScr(node.gameObject, "Game.Behaviours.CommonTabToggleLeftCell")
            if nodeScr then
                local go = GameUtils.GetRedPointGo(nodeScr.Text)
                if go then
                    local isCanDraw = FishingUtils.IsCanDrawReard(v.id)
                    KTool.SetActive(go, isCanDraw)
                end
            end
        end 
    end
end

function UIFshPoolCollectionDialog:RefreshCurTooggleType(type)
    KTool.SetActive(self.Empty, true)
    KTool.SetActive(self.Content, false)
    self._curSelectItmeInd = 0

    self._curSelectGroupId = checkString(type)
    self._allEasterEggsId = self:GetAllEasterEggsId(type)
    if self._isInitList then
        self.GoodNodeList:SetListItemCount(table.count(self._allEasterEggsId))
    else
        self.GoodNodeList:InitListView(0, Bind(self, self.OnRefreshIndex), nil, Bind(self, self.OnGetListItemByIndex))
        self.GoodNodeList:SetListItemCount(table.count(self._allEasterEggsId))
        self._isInitList = true
    end

    self:RefreshBoxInfo()
end

--获取该类型所有的彩蛋
function UIFshPoolCollectionDialog:GetAllEasterEggsId(type)
    local data = self._allEasterEggsGroup[checkString(type)]
    local t = CfUtils.Split(data.item)
    return t
end

function UIFshPoolCollectionDialog:OnGetListItemByIndex(go)
    if isNull(go) then
        return
    end
end

function UIFshPoolCollectionDialog:OnRefreshIndex(go, index, row, column)
    if index < 0 then
        return nil
    end

    local cell = go
    local id = self._allEasterEggsId[index + 1]
    local vo = FishingUtils.GetFishEasterEggsConditionVo(id)

    local scr = CfUtils.GetLuaScr(cell, UIFshPoolCollectionItemNode)
    if scr then
        scr:Refresh(vo, function()
            self:ChooseGoods(index + 1)
        end)

        --[[
        if (index + 1) == self._curSelectItmeInd then
            scr:RefreshSelectActive(true)
            self:RefreshInfo()
        end
        ]]
    end
end

--选择物品
function UIFshPoolCollectionDialog:ChooseGoods(ind)
    ind = checkNumber(ind)
    local go
    local lastSelectInd = self._curSelectItmeInd
    if checkNumber(lastSelectInd) > 0 then
        go = self.GoodNodeList:GetShownItemByItemIndex(lastSelectInd - 1)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, UIFshPoolCollectionItemNode)
            if lastScr then
                lastScr:RefreshSelectActive(false)
            end
        end
    end

    self._curSelectItmeInd = ind
    local curSelectInd = self._curSelectItmeInd
    if checkNumber(curSelectInd) > 0 then
        go = self.GoodNodeList:GetShownItemByItemIndex(curSelectInd - 1)
        if go then
            local curScr = CfUtils.GetLuaScr(go, UIFshPoolCollectionItemNode)
            if curScr then
                curScr:RefreshSelectActive(true)
            end
        end
    end
    self:RefreshGoodInfo()
end

function UIFshPoolCollectionDialog:RefreshGoodInfo()
    if checkNumber(self._curSelectItmeInd) < 1 then
        return
    end
    KTool.SetActive(self.Empty, false)
    KTool.SetActive(self.Content, true)

    local id = self._allEasterEggsId[self._curSelectItmeInd]

    local isUnlock = FishingUtils.IsUnlockEasterEggsId(id)
    KTool.SetActive(self.ImgIconNormal, isUnlock)
    KTool.SetActive(self.ImgUnknow, not isUnlock)
    KTool.SetActive(self.TitleGroup, not isUnlock)

    local vo = FishingUtils.GetFishEasterEggsConditionVo(id)
    if vo then 
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
        if goodsVo then
            CfUtils.FillText(self.Text, isUnlock and goodsVo.name or "???")
            CfUtils.SetUISwitchImage(self.ImgBgRare, checkNumber(goodsVo.quality))
            CfUtils.FillImage(self.ImgIconNormal, goodsVo.photoPath)
        end

        if not isUnlock then
            CfUtils.FillText(self.TextDescribe, vo.desc)
        else
            CfUtils.FillText(self.TextDescribe, goodsVo.desc)
        end
    end
end

--宝箱详情
function UIFshPoolCollectionDialog:RefreshBoxInfo()
    local groupVo = self._allEasterEggsGroup[self._curSelectGroupId]
    local curNum, allNum = FishingUtils.GetEasterEggsGetNum(groupVo.id)

    CfUtils.FillText(self.TextNumber, "<color=#7fffec>"..curNum.."</color>/"..allNum)
    CfUtils.FillText(self.TextTitle, localize("收集进度"))
    self.Slider.value = curNum/allNum

    local isGet = FishingUtils.IsDrawEasterEggsReward(groupVo.id)
    CfUtils.SetUISwitchImage(self.BoxIconNormal, isGet and 2 or 1)
    KTool.SetActive(self.ImgHasReceived, isGet)

    if curNum >= allNum then
        if not isGet then
            KTool.SetActive(self.StasusCanReceive, true)
            KTool.SetActive(self.UIFX_FshPoolCollectionDialog, true)
        else
            KTool.SetActive(self.StasusCanReceive, false)
            KTool.SetActive(self.UIFX_FshPoolCollectionDialog, false)
        end
    else
        KTool.SetActive(self.StasusCanReceive, false)
        KTool.SetActive(self.UIFX_FshPoolCollectionDialog, false)
    end
end

--领取奖励
function UIFshPoolCollectionDialog:OnBtnDrawReward()
    local groupVo = self._allEasterEggsGroup[self._curSelectGroupId]
    local isGet = FishingUtils.IsDrawEasterEggsReward(groupVo.id)
    if isGet then
        GameUtils.Toast(localize("该奖励已领取"))
        return
    end
    local curNum, allNum = FishingUtils.GetEasterEggsGetNum(groupVo.id)
    if curNum < allNum then
        local t = {}
        local t1 = CfUtils.Split(groupVo.reward)
        local t2 = CfUtils.Split(groupVo.rewardNum)
        for k, v in pairs(t1) do
            table.insert(t, {
                goodsId = t1[k],
                num = t2[k]
            })
        end
        GameUtils.ShowCommonTipsBoardRewardPreview(self.BoxIconNormal.gameObject, t, localize('奖励预览:'), false)
        return
    end
    comp:DrawEasterEggsGroupRewards(self._curSelectGroupId, function(rewards)
        self:RefreshBoxInfo()
        CS.Engine.UI.UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
        self:RefreshRedPoint()
    end)
end

