    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
    end))
    return coWait
end

function UIFshPoolCollectionDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        GameUtils.SetRedPointNum(Constants.RedPointConst.PhoneFishCollection, FishingUtils.IsHaveNoDrawReard() and 1 or 0)
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return UIFshPoolCollectionDialog
